WITH exploded AS (SELECT id, customer_id, coupon_codes, pos, entry.product_id, entry.price, entry.promo FROM carts LATERAL VIEW POSEXPLODE(items) x AS pos, entry) SELECT CASE WHEN pos >= 3 THEN 'LARGE' ELSE 'SMALL' END AS pos_tier, CASE WHEN price >= 236 THEN 'PREMIUM' ELSE 'STANDARD' END AS price_tier, PERCENTILE_APPROX(pos, ARRAY(0.25, 0.5, 0.75)) AS pos_quartiles, COUNT(CASE WHEN promo = 'BUNDLE' THEN 1 END) AS bundle_count, COUNT(*) FILTER (WHERE promo = 'BUNDLE') AS bundle_rows, COUNT(*) AS cnt, SIZE(COLLECT_SET(promo)) AS num_promos, COUNT(DISTINCT id) AS distinct_ids FROM exploded GROUP BY pos_tier, price_tier ORDER BY bundle_count
